#!/usr/bin/env bash
# ci-walden desk-tool v6 — generated by ci-walden tenant-init
# contract: run from inside the repo; 'bash ci-walden/desk.sh' prints the commands
# regenerating this file on an unchanged repo is a no-op diff
# conformance: sha256:fdc7141c10095dc8febe4fb19bb2872bdfa7caecf5dfe34bb890ad36ed6f8e13
set -eo pipefail
# The desk half of the ci-walden contract. The desk gate decides; CI is
# the clean-room witness. This tool runs the two lanes from verify.json,
# records each pass against the exact content it ran on, guards pushes
# with those records, and guards deploys with the CI check.

CI_WALDEN_CHECK="ci-walden/full-pipeline"
CI_WALDEN_APP_ID=4666382

ci_walden_usage() {
  cat >&2 <<'EOF'
usage: bash ci-walden/desk.sh <command>

  gate      run the fast lane (verify.json "gate") and record a pass
  verify    run the full gate (the same file CI runs) and record a pass
            --clean [<commit>]  run on a fresh clone of one commit
                                (default HEAD), not on this checkout
            --linux [<commit>]  the same, inside the Linux image named
                                by verify.json "linux_image" (opt-in:
                                for runner-only reds)
  green     deploy gate: pass only when this commit has a green CI check
            --override "<reason>"  deploy anyway, and record why
  install   install the pre-push hook in this clone
EOF
}

# ci_walden_field <key>: print the string at verify.json[key], or fail.
ci_walden_field() {
  if command -v python3 >/dev/null 2>&1; then
    python3 -c '
import json, sys
v = json.load(open("verify.json")).get(sys.argv[1])
if not isinstance(v, str) or not v.strip():
    sys.exit(3)
sys.stdout.write(v)' "$1"
  elif command -v node >/dev/null 2>&1; then
    node -e '
const v = JSON.parse(require("fs").readFileSync("verify.json", "utf8"))[process.argv[1]];
if (typeof v !== "string" || !v.trim()) process.exit(3);
process.stdout.write(v);' "$1"
  elif command -v jq >/dev/null 2>&1; then
    jq -ej --arg k "$1" '.[$k] | strings | select(test("\\S"))' verify.json
  else
    echo "ci-walden: python3, node, or jq is needed to read verify.json" >&2
    return 4
  fi
}

# ci_walden_trees: print the tree ids this working tree can be recorded
# under, on one line. The first is HEAD plus every change to tracked
# files; the second also includes untracked files that are not ignored.
# A commit made from this content has one of those two trees. A commit
# of only some of the changes has neither, and that is correct: it is
# not the content the lane ran on.
ci_walden_trees() {
  local d idx a b
  if ! git rev-parse -q --verify HEAD >/dev/null 2>&1; then
    return 0
  fi
  d=$(mktemp -d "${TMPDIR:-/tmp}/ci-walden-index.XXXXXX")
  idx="$d/index"
  a=""
  b=""
  if GIT_INDEX_FILE="$idx" git read-tree HEAD >/dev/null 2>&1; then
    if GIT_INDEX_FILE="$idx" git add -u . >/dev/null 2>&1; then
      a=$(GIT_INDEX_FILE="$idx" git write-tree 2>/dev/null || true)
    fi
    if GIT_INDEX_FILE="$idx" git add -A . >/dev/null 2>&1; then
      b=$(GIT_INDEX_FILE="$idx" git write-tree 2>/dev/null || true)
    fi
  fi
  rm -rf "$d"
  printf '%s %s\n' "$a" "$b"
}

ci_walden_receipts() {
  printf '%s/ci-walden/receipts' "$(git rev-parse --git-common-dir)"
}

# ci_walden_has <lane> <tree>
ci_walden_has() {
  [ -f "$(ci_walden_receipts)/$1/$2" ]
}

# ci_walden_record <lane> <tree>
ci_walden_record() {
  local dir
  dir="$(ci_walden_receipts)/$1"
  mkdir -p "$dir"
  date -u +%Y-%m-%dT%H:%M:%SZ >"$dir/$2"
}

# ci_walden_install [quiet]: write the pre-push hook for this clone.
# It honours core.hooksPath and never overwrites a hook it did not write.
ci_walden_install() {
  local quiet=${1:-} dir hook marker want
  marker='# ci-walden pre-push (managed)'
  dir=$(git rev-parse --git-path hooks)
  hook="$dir/pre-push"
  want=$(cat <<EOF
#!/bin/sh
$marker — regenerate with: bash ci-walden/desk.sh install
root=\$(git rev-parse --show-toplevel) || exit 0
[ -f "\$root/ci-walden/desk.sh" ] || exit 0
exec bash "\$root/ci-walden/desk.sh" hook "\$@"
EOF
)
  if [ -f "$hook" ]; then
    if ! grep -qF "$marker" "$hook"; then
      echo "ci-walden: $hook exists and is not managed by ci-walden; pushes are NOT guarded." >&2
      echo "  add this line to it:  bash ci-walden/desk.sh hook \"\$@\" || exit 1" >&2
      return 1
    fi
    if [ "$(cat "$hook")" = "$want" ]; then
      if [ "$quiet" != quiet ]; then
        echo "ci-walden: pre-push hook already installed at $hook"
      fi
      return 0
    fi
  fi
  mkdir -p "$dir"
  printf '%s\n' "$want" >"$hook"
  chmod +x "$hook"
  echo "ci-walden: pre-push hook installed at $hook"
}

# ci_walden_run <gate|verify>: run a lane and record the pass.
ci_walden_run() {
  local lane=$1 cmd before after tree rc=0 recorded=0
  ci_walden_install quiet || true
  before=$(ci_walden_trees)
  if [ "$lane" = verify ]; then
    bash ci-walden/tenant.sh || rc=$?
  else
    if ! cmd=$(ci_walden_field gate); then
      echo "ci-walden: verify.json has no usable \"gate\" command" >&2
      return 2
    fi
    echo "ci-walden: gate — $cmd"
    bash -eo pipefail -c "$cmd" || rc=$?
  fi
  if [ "$rc" -ne 0 ]; then
    echo "ci-walden: $lane FAILED (exit $rc); nothing recorded" >&2
    return "$rc"
  fi
  if [ -z "${before// /}" ]; then
    echo "ci-walden: $lane passed (this repository has no commit yet, so nothing is recorded)"
    return 0
  fi
  after=$(ci_walden_trees)
  for tree in $before; do
    case " $after " in
      *" $tree "*)
        ci_walden_record "$lane" "$tree"
        recorded=1
        ;;
    esac
  done
  if [ "$recorded" -eq 1 ]; then
    echo "ci-walden: $lane passed; recorded for this content"
  else
    echo "ci-walden: $lane passed, but files changed during the run; NOT recorded. Commit, then run it again." >&2
  fi
}

# ci_walden_run_clean <gate|verify> [<commit>]: run a lane on a fresh
# local clone of one commit and record the pass against that commit.
# This is the lane for a shared checkout: other people's uncommitted
# work stays where it is, and the run sees only what was committed. It
# runs provisioning the way the CI runner does.
ci_walden_run_clean() {
  local lane=$1 rev=${2:-HEAD} sha tree short d rc=0
  if ! sha=$(git rev-parse -q --verify "$rev^{commit}"); then
    echo "ci-walden: '$rev' is not a commit" >&2
    return 2
  fi
  tree=$(git rev-parse "$sha^{tree}")
  short=$(git rev-parse --short "$sha")
  ci_walden_install quiet || true
  d=$(mktemp -d "${TMPDIR:-/tmp}/ci-walden-clean.XXXXXX")
  echo "ci-walden: $lane --clean — fresh clone of $short in $d"
  if ! git clone -q --shared --no-checkout "$PWD" "$d/repo" ||
    ! git -C "$d/repo" checkout -q --detach "$sha"; then
    echo "ci-walden: could not make a clean clone of $short" >&2
    rm -rf "$d" || true
    return 3
  fi
  (
    cd "$d/repo"
    export CI_WALDEN_CLEAN_ROOM=1
    if [ "$lane" = verify ]; then
      exec bash ci-walden/tenant.sh
    fi
    if ! cmd=$(ci_walden_field gate); then
      echo "ci-walden: verify.json has no usable \"gate\" command" >&2
      exit 2
    fi
    if [ -f ci-walden/provision.sh ]; then
      echo "ci-walden: provision — ci-walden/provision.sh"
      . ci-walden/provision.sh
    fi
    echo "ci-walden: gate — $cmd"
    exec bash -eo pipefail -c "$cmd"
  ) || rc=$?
  if [ "$rc" -ne 0 ]; then
    echo "ci-walden: $lane --clean FAILED on $short (exit $rc); nothing recorded. The clone is kept at $d" >&2
    return "$rc"
  fi
  rm -rf "$d" || true
  ci_walden_record "$lane" "$tree"
  echo "ci-walden: $lane passed on a clean clone of $short; recorded for that commit"
}

# ci_walden_run_linux <gate|verify> [<commit>]: the clean lane inside a
# Linux container. The image is named by verify.json "linux_image" in
# that commit; it must already exist on this host, and nothing else is
# ever used in its place. The container runs offline and hardened, is
# stamped for docker_maid at creation, and is removed when it ends.
ci_walden_run_linux() {
  local lane=$1 rev=${2:-HEAD} sha tree short d image stamp name rc=0 script
  if ! sha=$(git rev-parse -q --verify "$rev^{commit}"); then
    echo "ci-walden: '$rev' is not a commit" >&2
    return 2
  fi
  tree=$(git rev-parse "$sha^{tree}")
  short=$(git rev-parse --short "$sha")
  for tool in docker docker_maid; do
    if ! command -v "$tool" >/dev/null 2>&1; then
      echo "ci-walden: --linux needs $tool on PATH" >&2
      return 4
    fi
  done
  ci_walden_install quiet || true
  d=$(mktemp -d "${TMPDIR:-/tmp}/ci-walden-linux.XXXXXX")
  # A full local clone, not --shared: the container cannot follow an
  # alternates path back into this checkout.
  if ! git clone -q --no-checkout "$PWD" "$d/repo" ||
    ! git -C "$d/repo" checkout -q --detach "$sha"; then
    echo "ci-walden: could not make a clean clone of $short" >&2
    rm -rf "$d" || true
    return 3
  fi
  if ! image=$(cd "$d/repo" && ci_walden_field linux_image); then
    echo "ci-walden: verify.json in $short names no \"linux_image\"; --linux has no image to run" >&2
    rm -rf "$d" || true
    return 2
  fi
  if ! docker image inspect "$image" >/dev/null 2>&1; then
    echo "ci-walden: Linux image '$image' is not on this host; build it first (nothing else is used in its place)" >&2
    rm -rf "$d" || true
    return 2
  fi
  if ! stamp=$(docker_maid stamp --owner ci-walden --docker-args); then
    echo "ci-walden: docker_maid could not stamp the container; not starting it" >&2
    rm -rf "$d" || true
    return 4
  fi
  script="$(declare -f ci_walden_field)"'
set -eo pipefail
mkdir -p /tmp/check
cp -R /source/. /tmp/check/repo
cd /tmp/check/repo
git config --global --add safe.directory "*"
export CI_WALDEN_CLEAN_ROOM=1
if [ "$1" = verify ]; then exec bash ci-walden/tenant.sh; fi
cmd=$(ci_walden_field gate) || { echo "ci-walden: verify.json has no usable \"gate\" command" >&2; exit 2; }
if [ -f ci-walden/provision.sh ]; then echo "ci-walden: provision — ci-walden/provision.sh"; . ci-walden/provision.sh; fi
echo "ci-walden: gate — $cmd"
exec bash -eo pipefail -c "$cmd"'
  name="ci-walden-linux-$(date +%s)-$$"
  echo "ci-walden: $lane --linux — $short in $image"
  # shellcheck disable=SC2086 # the stamp is a list of --label arguments
  docker run --rm --pull never --name "$name" $stamp \
    --network none --cap-drop ALL --security-opt no-new-privileges \
    --user 65534:65534 --pids-limit 512 --memory 5g --cpus 4 --read-only \
    --shm-size 512m --tmpfs /tmp:rw,nosuid,nodev,exec,size=8g \
    --tmpfs /nonexistent:rw,nosuid,nodev,exec,uid=65534,gid=65534,mode=0700 \
    -e HOME=/nonexistent \
    --mount "type=bind,source=$d/repo,target=/source,readonly" \
    --entrypoint bash "$image" -c "$script" ci-walden "$lane" </dev/null || rc=$?
  rm -rf "$d" || true
  if [ "$rc" -ne 0 ]; then
    echo "ci-walden: $lane --linux FAILED on $short (exit $rc); nothing recorded" >&2
    return "$rc"
  fi
  ci_walden_record "$lane" "$tree"
  echo "ci-walden: $lane passed in Linux on $short; recorded for that commit"
}

# ci_walden_hook <remote> <url>: the pre-push guard. Git feeds one line
# per pushed ref on stdin: <local ref> <local sha> <remote ref> <remote sha>.
ci_walden_hook() {
  local remote=${1:-origin} default="" fail=0
  local local_sha remote_ref branch lane tree short
  default=$(git symbolic-ref -q --short "refs/remotes/$remote/HEAD" 2>/dev/null || true)
  default=${default#"$remote"/}
  while read -r _ local_sha remote_ref _; do
    if [ -z "$local_sha" ]; then
      continue
    fi
    case "$local_sha" in
      *[!0]*) ;;
      *) continue ;; # a deletion pushes nothing to check
    esac
    case "$remote_ref" in
      refs/heads/*) ;;
      *) continue ;; # tags and other refs are not gated
    esac
    branch=${remote_ref#refs/heads/}
    lane=gate
    case "$branch" in
      ci/*) lane=verify ;;
    esac
    if [ -n "$default" ]; then
      if [ "$branch" = "$default" ]; then
        lane=verify
      fi
    else
      case "$branch" in
        main | master) lane=verify ;;
      esac
    fi
    tree=$(git rev-parse "$local_sha^{tree}")
    short=$(git rev-parse --short "$local_sha")
    if ci_walden_has verify "$tree"; then
      continue
    fi
    if [ "$lane" = gate ]; then
      if ci_walden_has gate "$tree"; then
        continue
      fi
      # The fast lane takes seconds, so run it here when the pushed
      # commit is exactly what is checked out.
      if [ "$(git rev-parse HEAD)" = "$local_sha" ] && git diff --quiet HEAD --; then
        echo "ci-walden: no recorded gate pass for $short; running the gate now" >&2
        if ci_walden_run gate </dev/null >&2 && ci_walden_has gate "$tree"; then
          continue
        fi
      fi
    fi
    fail=1
    echo "ci-walden: push BLOCKED — '$branch' needs a recorded '$lane' pass for commit $short." >&2
    if [ "$lane" = verify ]; then
      echo "  '$branch' books a CI run, so the full gate must pass at the desk first." >&2
    fi
    echo "  run:  bash ci-walden/desk.sh $lane --clean $short" >&2
    echo "  (or, on a checkout of $short with no uncommitted changes:  bash ci-walden/desk.sh $lane)" >&2
  done
  return "$fail"
}

# ci_walden_slug: owner/name of the origin remote.
ci_walden_slug() {
  git remote get-url origin | sed -E 's#^(https?://[^/]+/|ssh://[^/]+/|[^@/]+@[^:/]+:)##; s#\.git$##; s#/$##'
}

# ci_walden_check_state <slug> <sha>: print success, none, a conclusion
# (failure, cancelled, timed_out ...) or a status (queued, in_progress).
# Only a check run posted by the ci-walden GitHub App counts.
ci_walden_check_state() {
  local path="repos/$1/commits/$2/check-runs?per_page=100" token
  if command -v gh >/dev/null 2>&1; then
    gh api "$path" --jq "[.check_runs[] | select(.name == \"$CI_WALDEN_CHECK\" and .app.id == $CI_WALDEN_APP_ID)] | sort_by(.id) | last | if . == null then \"none\" elif .status == \"completed\" then .conclusion else .status end"
    return
  fi
  token=${GH_TOKEN:-${GITHUB_TOKEN:-}}
  if [ -z "$token" ]; then
    echo "ci-walden: gh, or GH_TOKEN / GITHUB_TOKEN, is needed to read the CI check" >&2
    return 4
  fi
  curl -fsS -H "Authorization: Bearer $token" -H "Accept: application/vnd.github+json" "https://api.github.com/$path" |
    python3 -c '
import json, sys
name, app = sys.argv[1], int(sys.argv[2])
runs = [r for r in json.load(sys.stdin).get("check_runs", [])
        if r.get("name") == name and (r.get("app") or {}).get("id") == app]
if not runs:
    print("none")
else:
    r = max(runs, key=lambda r: r.get("id", 0))
    print(r.get("conclusion") if r.get("status") == "completed" else r.get("status"))' "$CI_WALDEN_CHECK" "$CI_WALDEN_APP_ID"
}

# ci_walden_log <result> <state> <dirty> <reason>: one line per deploy
# decision, kept on this machine so the gate can be reviewed later.
ci_walden_log() {
  local dir file reason
  dir="${XDG_STATE_HOME:-$HOME/.local/state}/ci-walden"
  file="$dir/deploy-gate.jsonl"
  reason=$(printf '%s' "$4" | tr '\n\r\t' '   ' | sed 's/\\/\\\\/g; s/"/\\"/g')
  mkdir -p "$dir" 2>/dev/null || return 0
  printf '{"at":"%s","repo":"%s","sha":"%s","result":"%s","state":"%s","dirty":%s,"reason":"%s"}\n' \
    "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$CI_WALDEN_SLUG" "$CI_WALDEN_HEAD" "$1" "$2" "$3" "$reason" >>"$file" 2>/dev/null || true
}

# ci_walden_green [--override "<reason>"]: the deploy gate.
ci_walden_green() {
  local reason="" override=0 state dirty=false
  while [ $# -gt 0 ]; do
    case "$1" in
      --override)
        override=1
        reason=${2:-}
        if [ -z "$reason" ]; then
          echo "ci-walden: --override needs a reason in quotes" >&2
          return 2
        fi
        shift 2
        ;;
      *)
        ci_walden_usage
        return 2
        ;;
    esac
  done
  CI_WALDEN_HEAD=$(git rev-parse HEAD)
  CI_WALDEN_SLUG=$(ci_walden_slug)
  if ! git diff --quiet HEAD --; then
    dirty=true
  fi
  if ! state=$(ci_walden_check_state "$CI_WALDEN_SLUG" "$CI_WALDEN_HEAD"); then
    state=unreadable
  fi
  if [ "$state" = success ] && [ "$dirty" = false ]; then
    ci_walden_log green "$state" "$dirty" ""
    echo "ci-walden: GREEN — $CI_WALDEN_CHECK passed on $(git rev-parse --short HEAD); deploy may proceed"
    return 0
  fi
  if [ "$dirty" = true ]; then
    echo "ci-walden: tracked files differ from HEAD; a deploy would ship content no check has seen" >&2
  fi
  case "$state" in
    success) ;;
    none) echo "ci-walden: no $CI_WALDEN_CHECK run exists for $(git rev-parse --short HEAD). CI runs on the default branch and ci/*; land or push it there first." >&2 ;;
    queued | in_progress) echo "ci-walden: the $CI_WALDEN_CHECK run for $(git rev-parse --short HEAD) is still $state; wait for it" >&2 ;;
    unreadable) echo "ci-walden: could not read the CI check for $CI_WALDEN_SLUG" >&2 ;;
    *) echo "ci-walden: $CI_WALDEN_CHECK is '$state' on $(git rev-parse --short HEAD); fix it at the desk, land the fix, then deploy" >&2 ;;
  esac
  if [ "$override" -eq 1 ]; then
    ci_walden_log override "$state" "$dirty" "$reason"
    echo "ci-walden: OVERRIDE recorded — deploying without a green check. Reason: $reason" >&2
    return 0
  fi
  ci_walden_log blocked "$state" "$dirty" ""
  echo "ci-walden: deploy BLOCKED. To deploy anyway:  bash ci-walden/desk.sh green --override \"<reason>\"" >&2
  return 1
}

cd "$(git rev-parse --show-toplevel)"
case "${1:-}" in
  gate | verify)
    lane=$1
    shift
    if [ "${1:-}" = --clean ] && [ $# -le 2 ]; then
      ci_walden_run_clean "$lane" "${2:-HEAD}"
    elif [ "${1:-}" = --linux ] && [ $# -le 2 ]; then
      ci_walden_run_linux "$lane" "${2:-HEAD}"
    elif [ $# -eq 0 ]; then
      ci_walden_run "$lane"
    else
      ci_walden_usage
      exit 2
    fi
    ;;
  green)
    shift
    ci_walden_green "$@"
    ;;
  hook)
    shift
    ci_walden_hook "$@"
    ;;
  install)
    ci_walden_install
    ;;
  *)
    ci_walden_usage
    exit 2
    ;;
esac
